css:
@import url("https://fonts.googleapis.com/css2?family=Kanit:ital,wght@0,500;0,700;1,700&family=Inclusive+Sans&display=swap");
:root{--nv:#10243E;--nv2:#1B3558;--cr:#FF6B5B;--sk:#DCEBF5;--wh:#fff;--gr:#4E5D70;--h:"Kanit",Impact,sans-serif;--b:"Inclusive Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--nv);background:var(--wh)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:700;margin:0;line-height:1}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--cr);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--cr);outline-offset:3px}
.hdr{background:var(--nv);color:#fff}.nav{display:flex;justify-content:space-between;align-items:center;height:78px;position:relative}.logo{font-family:var(--h);font-weight:700;font-size:24px;text-decoration:none}.logo i{color:var(--cr);font-style:normal}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none}.menu a:hover{color:var(--cr)}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;border-radius:8px;font-size:20px;cursor:pointer}
.hero{background:var(--nv);color:#fff;overflow:hidden}.hero .wrap{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:end}
.hero .t{padding:50px 0 80px}.hero h1{font-size:clamp(56px,8.4vw,120px);font-style:italic;text-transform:uppercase;line-height:.9}.hero h1 em{color:var(--cr);font-style:italic;display:block}
.hero p{font-size:19px;color:#C7D4E4;max-width:30em;margin:24px 0 30px}
.btn{display:inline-block;background:var(--cr);color:#fff;font:700 17px var(--h);text-decoration:none;padding:14px 26px;border-radius:10px;border:0;cursor:pointer;letter-spacing:.02em}.btn.l{background:transparent;box-shadow:inset 0 0 0 2px currentColor;color:inherit}
.row{display:flex;flex-wrap:wrap;gap:12px}
.hero .ph{position:relative;align-self:stretch;min-height:520px}.hero .ph img{position:absolute;inset:40px 0 0 0;width:100%;height:calc(100% - 40px);object-fit:cover;border-radius:24px 24px 0 0}
.badge{position:absolute;left:-30px;bottom:40px;background:var(--cr);color:#fff;border-radius:16px;padding:16px 20px;font-family:var(--h);z-index:2;line-height:1.1}.badge b{display:block;font-size:40px}
section{padding:90px 0}.sh{max-width:640px;margin-bottom:36px}.sh h2{font-size:clamp(40px,5.4vw,70px);text-transform:uppercase}.sh p{color:var(--gr);font-size:18px;margin:12px 0 0}
.find{background:var(--sk)}.fg{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:start}.fg>div{min-width:0}
.q{margin-bottom:24px}.q legend{font-family:var(--h);font-size:24px;font-weight:500;margin-bottom:10px}.q fieldset{border:0;padding:0;margin:0}
.opts{display:flex;flex-wrap:wrap;gap:10px}.opts label{cursor:pointer;position:relative}.opts input{position:absolute;opacity:0;left:0;top:0;width:1px;height:1px}.opts span{display:block;background:#fff;border:2px solid #fff;border-radius:40px;padding:10px 18px;font-weight:600}
.opts input:checked+span{background:var(--nv);color:#fff;border-color:var(--nv)}.opts input:focus-visible+span{outline:3px solid var(--cr);outline-offset:2px}
.rec{background:var(--nv);color:#fff;border-radius:22px;padding:30px;position:sticky;top:20px}.rec small{color:var(--cr);font-weight:700;font-size:15px}.rec h3{font-size:40px;text-transform:uppercase;margin:6px 0 12px}
.rec ul{padding-left:18px;color:#C7D4E4;margin:0 0 20px}.rec .pr{font-family:var(--h);font-size:30px;margin-bottom:18px}
.progs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.pg{border:2px solid var(--sk);border-radius:22px;padding:28px}.pg .n{font-family:var(--h);font-size:15px;color:var(--cr);font-weight:500}.pg h3{font-size:32px;text-transform:uppercase;margin:6px 0 10px}.pg p{color:var(--gr);margin:0 0 14px}
.pg dl{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;margin:0;font-size:15px}.pg dt{color:var(--gr)}.pg dd{margin:0;font-weight:700}
.stories{background:var(--nv);color:#fff}.stories .sh p{color:#C7D4E4}
.sg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.st{background:var(--nv2);border-radius:22px;padding:26px}.st h3{font-size:26px;text-transform:uppercase}.st .who{color:#9FB2C8;font-size:15px;margin:4px 0 18px}
.sw{display:inline-flex;background:var(--nv);border-radius:30px;padding:4px;margin-bottom:18px}.sw button{font:600 14px var(--b);border:0;background:transparent;color:#C7D4E4;padding:7px 14px;border-radius:30px;cursor:pointer}.sw button[aria-pressed=true]{background:var(--cr);color:#fff}
.m{margin-bottom:14px}.m div{display:flex;justify-content:space-between;font-size:15px;margin-bottom:6px}.m b{font-family:var(--h);font-size:20px}
.m .tr{height:10px;background:var(--nv);border-radius:10px;overflow:hidden}.m .tr i{display:block;height:100%;background:var(--cr);border-radius:10px;transition:width .6s}
.st blockquote{margin:18px 0 0;font-size:16px;color:#DDE6F0;border-left:3px solid var(--cr);padding-left:14px}
.book .wrap{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px}
form{border:2px solid var(--sk);border-radius:22px;padding:30px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
label.l{display:block;font-weight:700;font-size:15px;margin-bottom:6px}input,select,textarea{width:100%;font:16px var(--b);padding:12px;border:2px solid #C9D6E4;border-radius:10px;margin-bottom:14px;color:var(--nv);background:#fff}
.slots{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:16px}.slots button{font:600 15px var(--b);padding:11px 4px;border:2px solid #C9D6E4;border-radius:10px;background:#fff;cursor:pointer;color:var(--nv)}
.slots button[aria-pressed=true]{background:var(--cr);border-color:var(--cr);color:#fff}.slots button:disabled{text-decoration:line-through;color:#9AA7B6;background:#F3F6F9;cursor:not-allowed}
.msg{visibility:hidden;margin:12px 0 0;font-weight:700;color:#1B7A4B}.msg.on{visibility:visible}
footer{background:var(--nv);color:#9FB2C8;padding:34px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero .wrap,.fg,.book .wrap{grid-template-columns:1fr}.hero .ph{min-height:380px}.badge{left:16px}.progs,.sg{grid-template-columns:1fr}.rec{position:static}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:78px;left:0;right:0;background:var(--nv);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.fr{grid-template-columns:1fr}.slots{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const P={fresh:["Fresh Start","12 weeks, 2 sessions a week","£480 total"],strong:["Built Strong","16 weeks, 3 sessions a week","£890 total"],pain:["Pain-Free Moves","8 weeks, 2 sessions a week","£360 total"]};
function quiz(){const v=n=>document.querySelector(`input[name=${n}]:checked`).value;const g=v('g'),d=v('d'),e=v('e');let k=g==='back'?'pain':g==='strong'||(e==='lots'&&d!=='2')?'strong':'fresh';
const why={fresh:"You want steady fat loss with a plan that fits a busy week.",strong:"You want to lift with confidence and see numbers go up.",pain:"You want to move freely first. Strength comes after."}[k];
$('rn').textContent=P[k][0];$('rl').innerHTML=`<li>${why}</li><li>${P[k][1]}</li><li>${d==='2'?'2 days works fine. We make every session count.':d==='3'?'3 days is the sweet spot for most people.':'We add a home session on your extra days.'}</li>`;$('rp').textContent=P[k][2];$('bp').value=P[k][0]}
$('qz').addEventListener('change',quiz);quiz();
const S=[["Claire","Fresh Start, age 41","Down two dress sizes and I can run for a bus without dying. I still eat pizza on Fridays.",[["Waist (cm)",92,81,100],["Push-ups in a row",2,14,20],["Resting heart rate",78,64,90]]],["Imran","Built Strong, age 36","I'd never touched a barbell. Now the deadlift is my favourite part of the week.",[["Deadlift (kg)",40,120,140],["Squat (kg)",30,95,120],["Bench press (kg)",25,70,90]]],["Sue","Pain-Free Moves, age 52","My back used to ache every morning. After 8 weeks I'm gardening again.",[["Back pain (0 to 10)",7,2,10],["Toe touch (cm off floor)",22,4,30],["Walk without stopping (min)",15,50,60]]]];
function st(){$('sg').innerHTML=S.map((s,i)=>`<article class="st"><h3>${s[0]}</h3><p class="who">${s[1]}</p><div class="sw" role="group" aria-label="Show ${s[0]}'s numbers"><button type="button" aria-pressed="true" data-i="${i}" data-w="0">Week 1</button><button type="button" aria-pressed="false" data-i="${i}" data-w="1">Final week</button></div><div class="ms" id="ms${i}"></div><blockquote>"${s[2]}"</blockquote></article>`).join('');S.forEach((s,i)=>ms(i,0))}
function ms(i,w){$('ms'+i).innerHTML=S[i][3].map(m=>{const v=w?m[2]:m[1];return`<div class="m"><div><span>${m[0]}</span><b>${v}</b></div><div class="tr"><i style="width:${v/m[3]*100}%"></i></div></div>`}).join('')}
st();$('sg').onclick=e=>{const b=e.target.closest('button');if(!b)return;b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));ms(+b.dataset.i,+b.dataset.w)};
const T=["07:00","08:00","12:00","13:00","17:30","18:30","19:30","20:30"];let pick='';
function slots(){const d=new Date($('bd').value).getDate()||1;$('sl').innerHTML=T.map((t,i)=>`<button type="button" aria-pressed="false" ${(i+d)%3===0?`disabled aria-label="${t}, taken"`:''}>${t}</button>`).join('');pick=''}
const nd=new Date(Date.now()+2*864e5);$('bd').value=nd.toISOString().slice(0,10);$('bd').min=new Date().toISOString().slice(0,10);slots();$('bd').onchange=slots;
$('sl').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;$('sl').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));pick=b.textContent};
$('bf').onsubmit=e=>{e.preventDefault();const m=$('msg');m.textContent=pick?`Thanks ${$('bn').value}. I've pencilled you in for ${$('bd').value} at ${pick}. I'll text you to confirm.`:'Please pick a time first.';m.style.color=pick?'':'#C8341F';m.classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
